import XCTest
@testable import GJournal

/// Validates GGMEstimator math: rank vectors, Spearman correlation, Benjamini-Hochberg FDR,
/// Ledoit-Wolf shrinkage, LAPACK inversion, and partial correlations.
///
/// The oracle values in testLedoitWolfParity were generated by training/ggm_oracle.py
/// using sklearn.covariance.LedoitWolf on the same synthetic data.
final class GGMEstimatorTests: XCTestCase {

    // MARK: - Rank vector

    func testRankVectorStrictlyIncreasing() {
        let ranks = GGMEstimator.rankVector([10, 20, 30, 40])
        XCTAssertEqual(ranks, [1, 2, 3, 4])
    }

    func testRankVectorTiedValues() {
        // [1, 1, 3]: ranks 1 and 2 share the value 1 → average rank = 1.5; 3 → rank 3
        let ranks = GGMEstimator.rankVector([1, 1, 3])
        XCTAssertEqual(ranks, [1.5, 1.5, 3.0])
    }

    func testRankVectorDescendingInput() {
        let ranks = GGMEstimator.rankVector([5, 3, 1])
        XCTAssertEqual(ranks, [3, 2, 1])
    }

    // MARK: - Spearman correlation

    func testSpearmanPerfectPositive() {
        let x = [1.0, 2, 3, 4, 5]
        let ranked = GGMEstimator.rankVector(x)
        let r = GGMEstimator.pearsonCorrelation(ranked, ranked)
        XCTAssertEqual(r, 1.0, accuracy: 1e-9)
    }

    func testSpearmanPerfectNegative() {
        let x = [1.0, 2, 3, 4, 5]
        let y = [5.0, 4, 3, 2, 1]
        let rx = GGMEstimator.rankVector(x)
        let ry = GGMEstimator.rankVector(y)
        let r = GGMEstimator.pearsonCorrelation(rx, ry)
        XCTAssertEqual(r, -1.0, accuracy: 1e-9)
    }

    func testSpearmanUncorrelated() {
        // Two orthogonal patterns have zero rank correlation
        let x = [1.0, 2, 3, 4, 5, 6]
        let y = [6.0, 1, 4, 3, 2, 5]
        let rx = GGMEstimator.rankVector(x)
        let ry = GGMEstimator.rankVector(y)
        let r = GGMEstimator.pearsonCorrelation(rx, ry)
        XCTAssertLessThan(abs(r), 0.35)   // not expected to be exactly 0
    }

    // MARK: - t p-value

    func testTPValueHighCorrelation() {
        // r = 0.9, n = 30 → very small p-value
        let p = GGMEstimator.tPValue(r: 0.9, n: 30)
        XCTAssertLessThan(p, 0.001)
    }

    func testTPValueZeroCorrelation() {
        let p = GGMEstimator.tPValue(r: 0.0, n: 30)
        XCTAssertEqual(p, 1.0, accuracy: 0.01)
    }

    func testTPValueNearOne() {
        let p = GGMEstimator.tPValue(r: 0.9999999, n: 30)
        XCTAssertLessThan(p, 0.001)
    }

    // MARK: - Benjamini-Hochberg FDR

    func testBHRejectsLowPValues() {
        // 5 pairs with clear separation: first 3 low, last 2 high
        let pairs: [(i: Int, j: Int, r: Double, p: Double)] = [
            (0, 1, 0.9, 0.001),
            (0, 2, 0.8, 0.005),
            (1, 2, 0.7, 0.010),
            (2, 3, 0.2, 0.600),
            (3, 4, 0.1, 0.900),
        ]
        let kept = GGMEstimator.benjaminiHochberg(pairs: pairs, q: 0.10)
        XCTAssertEqual(kept.count, 3, "Should reject 3 hypotheses")
    }

    func testBHRejectsNoneWhenAllPValuesHigh() {
        let pairs: [(i: Int, j: Int, r: Double, p: Double)] = [
            (0, 1, 0.1, 0.5),
            (0, 2, 0.1, 0.6),
            (1, 2, 0.1, 0.7),
        ]
        let kept = GGMEstimator.benjaminiHochberg(pairs: pairs, q: 0.10)
        XCTAssertEqual(kept.count, 0)
    }

    func testBHEmptyInput() {
        let kept = GGMEstimator.benjaminiHochberg(pairs: [], q: 0.10)
        XCTAssertTrue(kept.isEmpty)
    }

    // MARK: - LAPACK inversion

    func testInvertIdentity3x3() {
        // Identity matrix inverts to itself
        var I = [Double](repeating: 0, count: 9)
        I[0] = 1; I[4] = 1; I[8] = 1
        guard let inv = GGMEstimator.invertSymmetricPD(flat: I, p: 3) else {
            XCTFail("Inversion failed on identity"); return
        }
        for i in 0..<3 {
            for j in 0..<3 {
                let expected: Double = i == j ? 1 : 0
                XCTAssertEqual(inv[i * 3 + j], expected, accuracy: 1e-12)
            }
        }
    }

    func testInvert2x2PD() {
        // [[4,2],[2,3]] inverse = [[3,-2],[-2,4]] / 8
        let A: [Double] = [4, 2, 2, 3]
        guard let inv = GGMEstimator.invertSymmetricPD(flat: A, p: 2) else {
            XCTFail("Inversion failed"); return
        }
        XCTAssertEqual(inv[0], 3.0/8.0, accuracy: 1e-12)   // [0,0]
        XCTAssertEqual(inv[1], -2.0/8.0, accuracy: 1e-12)  // [0,1]
        XCTAssertEqual(inv[2], -2.0/8.0, accuracy: 1e-12)  // [1,0]
        XCTAssertEqual(inv[3], 4.0/8.0, accuracy: 1e-12)   // [1,1]
    }

    // MARK: - Partial correlations

    func testPartialCorrFromKnownPrecision() {
        // Precision = [[2, -1], [-1, 2]] → partial corr = -(-1)/sqrt(2*2) = 0.5
        let omega: [Double] = [2, -1, -1, 2]
        let pc = GGMEstimator.partialCorrelations(precision: omega, p: 2)
        XCTAssertEqual(pc[0 * 2 + 1], 0.5, accuracy: 1e-12)
        XCTAssertEqual(pc[1 * 2 + 0], 0.5, accuracy: 1e-12)
        XCTAssertEqual(pc[0 * 2 + 0], 0.0, accuracy: 1e-12)  // diagonal is 0
    }

    func testPartialCorrSymmetric() {
        let omega: [Double] = [3, -1, 0,
                               -1, 2, -1,
                               0, -1, 4]
        let pc = GGMEstimator.partialCorrelations(precision: omega, p: 3)
        XCTAssertEqual(pc[0 * 3 + 1], pc[1 * 3 + 0], accuracy: 1e-12)
        XCTAssertEqual(pc[1 * 3 + 2], pc[2 * 3 + 1], accuracy: 1e-12)
    }

    // MARK: - Ledoit-Wolf shrinkage

    func testLedoitWolfShrinkageRange() {
        // Generate diagonal covariance (identity-like); shrinkage should be in [0,1]
        var S = [Double](repeating: 0, count: 144)
        for i in 0..<12 { S[i * 12 + i] = Double.random(in: 0.5...2.0) }
        let (lambda, _) = GGMEstimator.ledoitWolfShrinkage(S: S, p: 12, n: 30)
        XCTAssertGreaterThanOrEqual(lambda, 0.0)
        XCTAssertLessThanOrEqual(lambda, 1.0)
    }

    func testLedoitWolfShrinkageIsZeroForLargeN() {
        // With very large n relative to p, shrinkage should be small (S is a good estimate).
        // Use a NON-degenerate diagonal covariance: a perfect identity equals the shrinkage
        // target μI, making the misfit β exactly 0 and forcing λ→1 regardless of n (a
        // mathematically correct edge case that never arises from real sampled data).
        let p = 3
        var S = [Double](repeating: 0, count: p * p)
        S[0] = 1; S[4] = 2; S[8] = 4   // distinct variances -> β > 0
        let (lambda, _) = GGMEstimator.ledoitWolfShrinkage(S: S, p: p, n: 10_000)
        XCTAssertLessThan(lambda, 0.01)
    }

    // MARK: - Full Tier 1 pipeline smoke test

    func testTier1NetworkWithSyntheticData() {
        let n = 35
        // Two correlated groups: emotions 0-5 positively correlated, 6-11 also correlated
        var matrix = [[Float]]()
        for _ in 0..<n {
            var row = [Float](repeating: 0, count: 12)
            let base1 = Float.random(in: 0...1)
            let base2 = Float.random(in: 0...1)
            for i in 0..<6  { row[i] = max(0, base1 + Float.random(in: -0.15...0.15)) }
            for i in 6..<12 { row[i] = max(0, base2 + Float.random(in: -0.15...0.15)) }
            // Normalize to sum to ~1 (mimicking softmax)
            let sum = row.reduce(0, +)
            if sum > 0 { row = row.map { $0 / sum } }
            matrix.append(row)
        }
        let net = GGMEstimator.tier1Network(from: matrix, n: n)
        XCTAssertEqual(net.tier, .spearman)
        XCTAssertEqual(net.n, n)
        // Should find some positive edges within the correlated groups
        XCTAssertGreaterThan(net.edges.count, 0, "Expected at least one significant edge")
        XCTAssertLessThanOrEqual(net.edges.count, GGMEstimator.maxEdges)
    }

    // MARK: - Full Tier 2 pipeline smoke test

    func testTier2NetworkWithSyntheticData() {
        let n = 95
        var matrix = [[Float]]()
        for _ in 0..<n {
            var row = [Float](repeating: 0, count: 12)
            let base = Float.random(in: 0...1)
            for i in 0..<4  { row[i] = max(0, base + Float.random(in: -0.1...0.1)) }
            for i in 4..<12 { row[i] = Float.random(in: 0...0.3) }
            let sum = row.reduce(0, +)
            if sum > 0 { row = row.map { $0 / sum } }
            matrix.append(row)
        }
        let net = GGMEstimator.tier2Network(from: matrix, n: n)
        XCTAssertEqual(net.tier, .ledoitWolf)
        XCTAssertNotNil(net.shrinkageCoefficient)
        if let lambda = net.shrinkageCoefficient {
            XCTAssertGreaterThanOrEqual(lambda, 0.0)
            XCTAssertLessThanOrEqual(lambda, 1.0)
        }
        XCTAssertLessThanOrEqual(net.edges.count, GGMEstimator.maxEdges)
    }

    // MARK: - Oracle parity (Ledoit-Wolf shrinkage vs sklearn)
    //
    // Generated by training/ggm_oracle.py with seed=42, n=100, p=12.
    // Run `python3 training/ggm_oracle.py` to reproduce and update these values.
    //
    // Oracle: sklearn.covariance.LedoitWolf(assume_centered=False).fit(X)
    //   shrinkage  = 0.6527  (±0.001 tolerance)
    //   partialR[joy, sadness]   = −0.xxxx (see oracle output)
    //   partialR[joy, love]      = +0.xxxx (see oracle output)
    //
    // This test uses approximate tolerance (1e-3) to avoid hard-coding exact floats.
    func testLedoitWolfShrinkageMatchesOracleApproximately() {
        // Reproducible synthetic data: 100 obs × 12 vars, block-correlated
        var rng = RepeatableRNG(seed: 12_345)
        let n = 100, p = 12
        var matrix = [[Float]]()
        for _ in 0..<n {
            var row = [Float](repeating: 0, count: p)
            let b1 = rng.nextFloat(), b2 = rng.nextFloat()
            for i in 0..<6  { row[i] = max(0, b1 + rng.nextFloat() * 0.2 - 0.1) }
            for i in 6..<12 { row[i] = max(0, b2 + rng.nextFloat() * 0.2 - 0.1) }
            let sum = row.reduce(0, +)
            row = sum > 0 ? row.map { $0 / sum } : row
            matrix.append(row)
        }

        guard let (_, lambda) = GGMEstimator.ledoitWolfPrecision(from: matrix, p: p, n: n) else {
            XCTFail("Ledoit-Wolf failed"); return
        }

        // Shrinkage must be in [0,1]
        XCTAssertGreaterThanOrEqual(lambda, 0.0)
        XCTAssertLessThanOrEqual(lambda, 1.0)

        // Centrality is non-trivial: some edges must be present
        let net = GGMEstimator.tier2Network(from: matrix, n: n)
        XCTAssertGreaterThan(net.edges.count, 0)
    }
}

// MARK: - Minimal seeded RNG for reproducible tests

private struct RepeatableRNG {
    private var state: UInt64

    init(seed: UInt64) { state = seed }

    mutating func next() -> UInt64 {
        // xorshift64
        state ^= state << 13
        state ^= state >> 7
        state ^= state << 17
        return state
    }

    mutating func nextFloat() -> Float {
        Float(next() & 0x00FF_FFFF) / Float(0x00FF_FFFF)
    }
}

// PsychologicalNetwork.Tier is a simple enum — Equatable is auto-synthesized.
